/* Thermosys - ISOLATION ANTI-CONDENSATION : correction du calcul d epaisseur d isolant (le coefficient de convection par defaut de 9 W/m2K, deja un coefficient d echange, etait augmente du rayonnement : epaisseur sous-estimee de 6,3 mm au lieu de 9,8 mm sur le cas par defaut). Convection naturelle de Churchill et Chu, point de rosee ASHRAE/Hyland-Wexler (ecart <= 0,013 K contre CoolProp), validations, notes en FR/EN/ES.
   Met aussi a jour la page Validation et references. Tests tests\\isolation_regression.js (26 mutations, comparaison a un tableau publie).
   Usage (depuis le dossier files) :  node patch_isolation_v2.js */
'use strict';
const fs = require('fs'), path = require('path');
const file = process.argv[2] || path.join('dist', 'index.html');
if (!fs.existsSync(file)) { console.error('Fichier introuvable : ' + file); process.exit(2); }
const raw = fs.readFileSync(file, 'utf8'), crlf = raw.indexOf('\r\n') >= 0;
let s = crlf ? raw.replace(/\r\n/g, '\n') : raw;
const MOD = Buffer.from("", 'base64').toString('utf8');
const TEST = Buffer.from("", 'base64').toString('utf8');

const VMOD = Buffer.from("", 'base64').toString('utf8');
const VTEST = Buffer.from("", 'base64').toString('utf8');
function updateValidation(t) {
  const vo = '<script id="validation-46-module">', va = t.indexOf(vo);
  if (va < 0) { return t; }
  const ve = t.indexOf('</script>', va); if (ve < 0) { return t; }
  fs.writeFileSync(path.join('tests', 'validation_regression.js'), VTEST, 'utf8');
  return t.slice(0, va) + vo + '\n' + VMOD + t.slice(ve);
}
function writeTest() {
  fs.mkdirSync('tests', { recursive: true }); fs.writeFileSync(path.join('tests', 'isolation_regression.js'), TEST, 'utf8');
  const rd = path.join('tests', 'README_TESTS.txt'); let r = fs.existsSync(rd) ? fs.readFileSync(rd, 'utf8') : '';
  if (r.indexOf('isolation_regression.js') < 0) fs.writeFileSync(rd, r + (r && !/\n$/.test(r) ? '\n' : '') + '\nisolation_regression.js : calcul d epaisseur d isolant anti-condensation (point de rosee CoolProp, convection naturelle Churchill-Chu, bilan thermique, 2e methode) : suite complete et 26 mutations. Commande : node tests\\isolation_regression.js\n', 'utf8');
}
if (s.indexOf('THERMOSYS_ISOLATION_V1') >= 0) { writeTest(); console.log('Deja applique : test reecrit.'); process.exit(0); }
const open = '<script id="gaines-47-module">', a = s.indexOf(open);
if (a < 0) { console.error('ECHEC : appliquer d\'abord patch_gaines_ef_v1.js. Fichier non modifie.'); process.exit(3); }
if (s.indexOf(open, a + 1) >= 0) { console.error('ECHEC : module acoustique-45 en double. Fichier non modifie.'); process.exit(3); }
const e = s.indexOf('</script>', a);
if (e < 0) { console.error('ECHEC : fin du module acoustique-45 introuvable.'); process.exit(3); }
const ins = e + '</script>'.length;
s = s.slice(0, ins) + '\n<script id="isolation-48-module">\n' + MOD + '</script>' + s.slice(ins);
fs.mkdirSync('tests', { recursive: true });
s = updateValidation(s);
fs.writeFileSync(file, crlf ? s.replace(/\n/g, '\r\n') : s, 'utf8');
writeTest();
console.log('OK : module isolation-48 insere, page Validation mise a jour.');
